    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Exponential moving average with decay factor 0.9
    alpha = 0.9
    if observation['action'] == 'donate':
        new_rep = alpha * current_reputation + (1 - alpha) * 1.0
    else:
        new_rep = alpha * current_reputation + (1 - alpha) * (-1.0)
