    return max(-5.0, min(5.0, new_rep))

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Early rounds: be generous (donate if reputation > -1)
    if round_num <= 3:
        return recipient_reputation > -1.0

    # Later rounds: condition on past cooperation of partners
    if not my_history:
        return recipient_reputation > 0.0

    # Fraction of past partners who donated when we interacted with them
    coop_count = sum(1 for entry in my_history if entry['partner_action'] == 'donate')
    coop_ratio = coop_count / len(my_history)

    if coop_ratio >= 0.5:
        # If my partners have been cooperative, use moderate threshold
        return recipient_reputation > 0.0
    else:
        # If I've been exploited often, demand higher reputation
        return recipient_reputation > 1.5
